//! MetaStock add-on pack "metastock add-on's (more 40 mb.).rar" (research drive, MetaStock/@Systems &
//! Indicators/@Misc/; read in place with library/rarsys/tools/larc.py, read-only). Book id `msadd`.
//! System tests are the binary MetaStock files inside the pack:
//!  * `metastock spk misc system add-on/MS65PRFT.DTA` (103 records: the Equis "Systems!" sample tests
//!    N-xxx / O-xxx plus three user systems) with its custom formulas in `MS65FORM.DTA` (94 formulas);
//!  * four `MS50PRFT.DTA` files (candle, diff-neu indi, time-ind, vol & preis add-ons): the 86 live
//!    records are G. Morris systems already in the vault as `msws`; 85 are exact duplicates and skipped,
//!    one (POP CCI crossover w/ stops) stores a different Close Long and is run here.
//! Record layout used (read from the files themselves): MS65 header 4184 bytes, records 28371 bytes:
//! notes @0 (1024), name @1024 (41), four formulas @1065 + 2500*k (NUL-terminated); MS50 header 2178,
//! records 14637: notes @0, name @1024, formulas @1065 + 1024*k. Formula text is run exactly as stored.
//! Stops: each record has a five-entry binary stop block (MS65 @27065, MS50 @13357). No document on the
//! drive gives its layout. 102 of the 103 MS65 records and all 86 live MS50 records hold the same block
//! (every entry tag 0x4E24, every value 0.0); the 86 MS50 systems are printed in text (Wallstreet .doc,
//! vault `msws`) with no stops, so that block is read as "no stops" (a zero Maximum Loss / Profit stop
//! would close every trade at once, manual p.334). Records whose block differs (Alfa, N-BOL-C, O-STO-5T,
//! O-TXM-FP) are NotTestable: their stop fields cannot be confirmed.
//! Fills: MetaStock 6.5 keeps trade price / delay in the global System Tester options, not in the record
//! (no per-record field differs between systems); the MetaStock default is used: trade price close,
//! trade delay 0, as in `msws`.
//! Legacy syntax: When(a,op,b) = (a op b) (via `mslib::expand`); If(a,op,b,t,f) = If((a op b),t,f).
//! Fml("x") resolves to the formula whose name up to its ':' equals x without a trailing ':' (case-
//! insensitive): the only reading under which every call in Equis's own files resolves (e.g. Fml("sto-3m")
//! -> "STO-3M: STOCHASTIC 3-PERIOD MAX/MIN"). Transcription and checks: library/msadd/.
use crate::books::msws::{self, Eng, Exec, Sys, EXEC_DEFAULT};
use crate::connors::{Ctx, ParamDef, Params, Status, StrategyDef, Trade};
#[allow(unused_imports)]
use crate::connors::Status::{Live, NeedsData, NotTestable};
use std::sync::OnceLock;

pub const BOOK: &str = "msadd";
#[allow(dead_code)]
fn _exec_type_check(e: Exec) -> Exec { e }

fn fkey(s: &str) -> String { s.split(':').next().unwrap_or("").trim().to_ascii_uppercase() }
/// Fml() lookup into the pack's MS65FORM.DTA, returning the body with legacy syntax expanded.
pub fn fml(name: &str) -> Option<String> {
    static EXP: OnceLock<Vec<(String, String)>> = OnceLock::new();
    let t = EXP.get_or_init(|| FML.iter().map(|(n, b)| (fkey(n), expand(b))).collect());
    let k = name.trim().trim_end_matches(':').trim().to_ascii_uppercase();
    t.iter().find(|(n, _)| *n == k).map(|(_, b)| b.clone())
}

/// Split argument text at top-level commas (braces are comments).
fn split_args(s: &str) -> Vec<String> {
    let (mut out, mut cur, mut d, mut brace) = (vec![], String::new(), 0i32, false);
    for c in s.chars() {
        match c {
            '{' => brace = true,
            '}' => brace = false,
            '(' if !brace => d += 1,
            ')' if !brace => d -= 1,
            ',' if !brace && d == 0 => { out.push(std::mem::take(&mut cur)); continue; }
            _ => {}
        }
        cur.push(c);
    }
    out.push(cur);
    out
}
/// Drop {comments}.
fn strip_comments(s: &str) -> String {
    let mut out = String::new(); let mut b = false;
    for c in s.chars() { match c { '{' => b = true, '}' => b = false, _ if !b => out.push(c), _ => {} } }
    out
}
/// Legacy If(a,op,b,t,f) -> If(When(a,op,b),t,f), recursively; then When() via mslib::expand.
pub fn expand(src: &str) -> String { crate::books::mslib::expand(&if5(&strip_comments(src))) }
fn if5(src: &str) -> String {
    let b: Vec<char> = src.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == '"' { out.push(c); i += 1; while i < b.len() && b[i] != '"' { out.push(b[i]); i += 1; } if i < b.len() { out.push('"'); i += 1; } continue; }
        if c.is_ascii_alphabetic() && (i == 0 || !(b[i - 1].is_ascii_alphanumeric() || b[i - 1] == '_')) {
            let j0 = i;
            while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == '_') { i += 1; }
            let w: String = b[j0..i].iter().collect();
            let mut j = i;
            while j < b.len() && b[j].is_whitespace() { j += 1; }
            if w.eq_ignore_ascii_case("if") && j < b.len() && b[j] == '(' {
                let (mut k, mut d) = (j, 0i32);
                while k < b.len() { match b[k] { '(' => d += 1, ')' => { d -= 1; if d == 0 { break; } } _ => {} } k += 1; }
                if k < b.len() {
                    let a = split_args(&b[j + 1..k].iter().collect::<String>());
                    let a: Vec<String> = a.iter().map(|x| if5(x)).collect();
                    if a.len() == 5 && matches!(a[1].trim(), ">" | "<" | "=" | ">=" | "<=" | "<>") {
                        out.push_str(&format!("If(When({},{},{}),{},{})", a[0], a[1].trim(), a[2], a[3], a[4]));
                    } else {
                        out.push_str(&format!("{}({})", w, a.join(",")));
                    }
                    i = k + 1;
                    continue;
                }
            }
            out.push_str(&w);
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

fn leak(s: String) -> &'static str { Box::leak(s.into_boxed_str()) }
fn expanded(s: &Sys) -> [Option<String>; 4] { [0, 1, 2, 3].map(|k| s.f[k].map(expand)) }
fn consts_of(s: &Sys) -> Vec<f64> {
    let e = expanded(s);
    let srcs: Vec<&str> = e.iter().flatten().map(|x| x.as_str()).collect();
    msws::constants(&srcs)
}
const CONV: &str = "Fills: MetaStock defaults (trade price close, trade delay 0; the record has no fill field). Stops: none (the record's stop block is the all-zero block shared by systems whose text printouts show no stops). One position at a time; a position closes only by its own Close formula (checked from the bar after entry); an exit plus an opposite entry on one bar reverse; the last position stays open, marked to the last close. India: run on the index in place of the stocks/futures the pack was written for (instrument swap only); constants applied literally.";

static CAT: OnceLock<Vec<(&'static [&'static str], &'static str, bool)>> = OnceLock::new();
pub fn catalogue() -> Vec<StrategyDef> {
    let cache = CAT.get_or_init(|| SYS.iter().map(|s| {
        let lab = ["E|Enter Long: ", "X|Close Long: ", "E|Enter Short: ", "X|Close Short: "];
        let mut rules: Vec<&'static str> = s.f.iter().zip(lab).filter_map(|(f, l)| f.map(|f| leak(format!("{l}{f}")))).collect();
        let fl: &dyn Fn(&str) -> Option<String> = &fml;
        let mut refs: Vec<String> = vec![];
        for f in s.f.iter().flatten() { for r in msws::scan(&expand(f), fl).1 { if !refs.contains(&r) { refs.push(r); } } }
        for r in &refs {
            let k = r.trim().trim_end_matches(':').trim().to_ascii_uppercase();
            if let Some((n, b)) = FML.iter().find(|(n, _)| fkey(n) == k) { rules.push(leak(format!("F|Fml \"{n}\" = {b}"))); }
        }
        let live = s.status == Status::Live;
        let vol = live && expanded(s).iter().flatten().any(|f| msws::scan(f, fl).0);
        let notes = if live { leak(format!("{} Source: {}. {}", s.notes, s.page, CONV)) } else { leak(format!("{} Source: {}.", s.notes, s.page)) };
        (&*Box::leak(rules.into_boxed_slice()), notes, vol)
    }).collect());
    SYS.iter().zip(cache).map(|(s, (rules, notes, vol))| StrategyDef {
        id: s.id, name: s.name, group: s.group, session: 0,
        dir: match (s.f[0].is_some(), s.f[2].is_some()) { (true, true) => "Long/Short", (true, false) => "Long", (false, true) => "Short", _ => "Long/Short" },
        status: s.status, needs_volume: *vol, needs_vix: false, needs_series: &[], book: BOOK, rules, notes, claim: None,
    }).collect()
}
pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> {
    let s = SYS.iter().find(|s| s.id == id)?;
    let v = match s.status { Status::Live => s.name, Status::NeedsData(_) => "data missing", Status::NotTestable(_) => "not testable" };
    Some((s.family.0, s.family.1, v))
}
pub fn params(id: &str) -> Option<Vec<ParamDef>> {
    let s = SYS.iter().find(|s| s.id == id && s.status == Status::Live)?;
    let mut v = vec![];
    if s.f[0].is_some() && s.f[2].is_some() { v.push(ParamDef { key: "side", label: "Sides traded: 0 = both as stored, 1 = long side only, -1 = short side only", def: 0., min: -1., max: 1., step: 1. }); }
    for c in consts_of(s) {
        let int = c.fract() == 0.0;
        let (min, max, step) = if int && c >= 5.0 { ((c * 0.5).round().max(1.0), (c * 2.0).round(), 1.0) } else { (c * 0.5, c * 2.0, (c / 10.0 * 1000.0).round() / 1000.0) };
        v.push(ParamDef { key: leak(msws::const_key(c)), label: leak(format!("Stored constant {c} (every use of {c} in this system's own formulas; Ref offsets and Fml bodies excluded)")), def: c, min, max, step: if step > 0.0 { step } else { 0.001 } });
    }
    Some(v)
}
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> {
    let s = SYS.iter().find(|s| s.id == id)?;
    if s.status != Status::Live || from >= to || to >= x.r.len() { return None; }
    let side = p.get("side").copied().unwrap_or(0.0).round() as i32;
    let map: Vec<(f64, f64)> = consts_of(s).into_iter().map(|c| (c, p.get(&msws::const_key(c)).copied().unwrap_or(c))).collect();
    let e = expanded(s);
    let srcs: [Option<&str>; 4] = [0, 1, 2, 3].map(|k| e[k].as_deref());
    let fl: &dyn Fn(&str) -> Option<String> = &fml;
    let mut eng = Eng::new(x, fl);
    let sig = msws::signals(&mut eng, srcs, &map, side).ok()?;
    Some(msws::simulate(x, from, to, &sig, s.exec))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn legacy_if_and_fml_lookup() {
        assert_eq!(if5(&strip_comments("If({ A }H,=,O,1,0)")), "If(When(H,=,O),1,0)");
        assert!(fml("sto-3m").is_some() && fml("can-9p:").is_some() && fml("CAN-HI-BULL").is_some());
        for s in SYS.iter().filter(|s| s.status == Status::Live) {
            for f in s.f.iter().flatten() { assert!(msws::parse(&expand(f)).is_ok(), "{} {}", s.id, f); }
        }
        for (n, _) in FML { assert!(msws::parse(&fml(&fkey(n)).unwrap()).is_ok(), "{n}"); }
    }
}

